/* ============================================================
   FIREZONE — Open World Battle Royale
   ============================================================ */
@font-face {
  font-family: 'Bebas Neue';
  src: url('fonts/BebasNeue-Regular.ttf') format('truetype');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-Regular.ttf') format('truetype');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-Medium.ttf') format('truetype');
  font-weight: 500; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-SemiBold.ttf') format('truetype');
  font-weight: 600; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-Bold.ttf') format('truetype');
  font-weight: 700; font-style: normal; font-display: swap;
}

:root {
  --orange: #ff6a1a;
  --orange-2: #ffb02e;
  --orange-hot: #ff8a1f;
  --cyan: #3ad8ff;
  --green: #6ee66a;
  --yellow: #ffd23f;
  --red: #ff3d3d;
  --ink: #07090d;
  --panel: rgba(11, 15, 21, 0.88);
  --panel-2: rgba(17, 22, 30, 0.92);
  --line: rgba(255, 255, 255, 0.12);
  --line-hot: rgba(255, 122, 36, 0.5);
  --text: #eef4f8;
  --muted: #8e9aa8;
  --hud-scale: 1;
  --gap: 10px;
  --ch-len: 9px;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden; background: #06080b; color: var(--text);
  font-family: 'Rajdhani', 'Trebuchet MS', sans-serif;
  -webkit-user-select: none; user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
body { touch-action: none; }
button, input, select { font-family: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game-canvas {
  position: absolute; inset: 0; width: 100%; height: 100%;
  display: block; outline: none;
  background: #0a0f16;
}
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(0,0,0,.22) 78%, rgba(0,0,0,.5) 100%);
}
#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 12; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255,30,20,.18) 65%, rgba(210,0,0,.55) 100%);
  transition: opacity .14s ease-out;
}
#low-health {
  position: absolute; inset: 0; pointer-events: none; z-index: 11; opacity: 0;
  box-shadow: inset 0 0 140px 50px rgba(200, 20, 10, .42);
  transition: opacity .4s ease;
}
#low-health.active { opacity: 1; animation: lowPulse 1.4s ease-in-out infinite; }
@keyframes lowPulse { 0%,100% { opacity:.45 } 50% { opacity:.95 } }

kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 19px; padding: 0 5px;
  border: 1px solid rgba(255,255,255,.24); border-bottom-color: rgba(255,255,255,.4);
  border-radius: 3px; background: rgba(255,255,255,.08);
  font-family: 'Rajdhani', sans-serif; font-size: 11px; font-weight: 700;
  color: #e9eef2; line-height: 1;
}

/* ============================================================
   LOADING
   ============================================================ */
.screen { position: absolute; inset: 0; z-index: 40; }
.loading-screen {
  background: #070a0f; display: flex; align-items: center; justify-content: center;
  z-index: 100;
}
.loading-grid {
  position: absolute; inset: -20%;
  background-image: linear-gradient(rgba(255,106,26,.07) 1px, transparent 1px), linear-gradient(90deg, rgba(255,106,26,.07) 1px, transparent 1px);
  background-size: 64px 64px; transform: perspective(500px) rotateX(58deg) scale(1.4);
  mask-image: radial-gradient(ellipse at center, #000 0%, transparent 70%);
  animation: gridDrift 18s linear infinite;
}
@keyframes gridDrift { to { background-position: 0 640px, 640px 0; } }
.loading-center { position: relative; text-align: center; width: min(440px, 86vw); z-index: 2; }
.brand-mark {
  width: 42px; height: 42px; display: inline-flex; align-items: center; justify-content: center;
  background: linear-gradient(145deg, var(--orange), #d53a05);
  color: #140900; font-family: 'Bebas Neue', Impact, sans-serif; font-size: 24px; letter-spacing: 1px;
  clip-path: polygon(10% 0, 100% 0, 90% 100%, 0 100%);
  box-shadow: 0 0 24px rgba(255,106,26,.5);
}
.brand-mark.large { width: 64px; height: 64px; font-size: 38px; margin-bottom: 12px; }
.loading-center h1 {
  font-family: 'Bebas Neue', Impact, sans-serif; font-weight: 400;
  font-size: clamp(56px, 10vw, 88px); letter-spacing: 5px; line-height: .9;
  margin: 0; color: #fff;
}
.loading-center h1 span { color: var(--orange); }
.loading-sub { color: var(--muted); letter-spacing: 6px; font-size: 12px; font-weight: 700; margin-top: 8px; }
.loader-bar {
  margin: 32px auto 10px; height: 7px; width: 100%; background: rgba(255,255,255,.08);
  clip-path: polygon(0 0, 100% 0, 98% 100%, 0 100%); overflow: hidden;
}
.loader-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #d64a0a, var(--orange), var(--orange-2)); transition: width .3s ease; box-shadow: 0 0 16px var(--orange); }
.loader-status { display: flex; justify-content: space-between; font-size: 11px; letter-spacing: 2px; color: var(--muted); font-weight: 600; }
.loader-status b { color: var(--orange); }
.loader-tip { margin-top: 34px; color: #a4b0bc; font-size: 12px; letter-spacing: 1.5px; min-height: 16px; }
.loading-foot { position: absolute; bottom: 26px; font-size: 10px; letter-spacing: 4px; color: #55606c; }

/* ============================================================
   LOBBY
   ============================================================ */
.lobby-screen {
  z-index: 30; display: flex; flex-direction: column;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(255,110,26,.11), transparent 48%),
    linear-gradient(90deg, rgba(4,6,9,.94) 0%, rgba(4,6,9,.62) 27%, rgba(4,6,9,.28) 50%, rgba(4,6,9,.72) 76%, rgba(4,6,9,.95) 100%),
    linear-gradient(0deg, rgba(4,6,9,.96) 0%, transparent 34%, transparent 70%, rgba(4,6,9,.86) 100%);
}
.lobby-shade { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(0,0,0,.34), transparent 30%, transparent 60%, rgba(0,0,0,.55)); }
.lobby-topbar {
  position: relative; z-index: 2; flex: 0 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: calc(14px + var(--safe-t)) calc(30px + var(--safe-r)) 14px calc(30px + var(--safe-l));
  border-bottom: 1px solid rgba(255,255,255,.08);
  background: linear-gradient(180deg, rgba(5,8,12,.72), rgba(5,8,12,.15));
  backdrop-filter: blur(8px);
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-copy { display: flex; flex-direction: column; line-height: 1; }
.brand-copy strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 25px; letter-spacing: 3px; font-weight: 400; }
.brand-copy span { color: var(--muted); font-size: 9px; letter-spacing: 3px; margin-top: 3px; }
.topbar-right { display: flex; align-items: center; gap: 14px; }
.online-pill { display: flex; align-items: center; gap: 7px; font-size: 10px; letter-spacing: 2px; color: #b9c4cf; }
.online-pill i { width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: blink 2s infinite; }
@keyframes blink { 50% { opacity: .35 } }
.ghost-btn {
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.18);
  color: #d9e2ea; font-weight: 700; font-size: 11px; letter-spacing: 2px;
  padding: 9px 16px; clip-path: polygon(7% 0, 100% 0, 93% 100%, 0 100%);
  transition: .18s ease;
}
.ghost-btn:hover { border-color: var(--orange); color: #fff; background: rgba(255,106,26,.14); }
.ghost-btn.danger { border-color: rgba(255,61,61,.4); color: #ff8f8f; }
.ghost-btn.danger:hover { background: rgba(255,61,61,.14); border-color: var(--red); }
.profile-chip { display: flex; align-items: center; gap: 9px; padding-left: 14px; border-left: 1px solid rgba(255,255,255,.1); }
.avatar {
  width: 34px; height: 34px; display: flex; align-items: center; justify-content: center;
  border-radius: 50%; background: linear-gradient(135deg, #303a48, #131820);
  border: 1px solid rgba(255,255,255,.2); color: var(--orange-2); font-weight: 700; font-size: 16px;
}
.profile-chip div { display: flex; flex-direction: column; line-height: 1.1; }
.profile-chip strong { font-size: 12px; letter-spacing: 1.5px; }
.profile-chip small { font-size: 9px; letter-spacing: 1.5px; color: var(--muted); }

.lobby-content {
  position: relative; z-index: 2; flex: 1 1 auto; min-height: 0;
  display: grid; grid-template-columns: minmax(230px, 272px) minmax(440px, 1fr) minmax(260px, 302px);
  gap: clamp(12px, 1.7vw, 26px);
  padding: 18px calc(30px + var(--safe-r)) 22px calc(30px + var(--safe-l));
  overflow: hidden;
}
.lobby-panel {
  align-self: center; max-height: 100%; overflow: auto; scrollbar-width: thin;
  background: linear-gradient(160deg, rgba(16,21,29,.92), rgba(8,11,16,.86));
  border: 1px solid rgba(255,255,255,.09);
  border-top: 2px solid rgba(255,106,26,.55);
  padding: 18px 18px 16px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%);
  box-shadow: 0 20px 60px rgba(0,0,0,.45);
  backdrop-filter: blur(9px);
}
.lobby-panel::-webkit-scrollbar { width: 4px; }
.lobby-panel::-webkit-scrollbar-thumb { background: rgba(255,106,26,.4); }
.panel-kicker { color: var(--orange); font-size: 9px; font-weight: 700; letter-spacing: 3px; }
.lobby-panel h2 { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 30px; letter-spacing: 2px; font-weight: 400; margin: 2px 0 14px; }

.rank-panel { text-align: center; }
.rank-badge { position: relative; width: 118px; height: 118px; margin: 6px auto 8px; display: flex; align-items: center; justify-content: center; }
.rank-shield {
  position: relative; z-index: 2; width: 86px; height: 98px;
  background: linear-gradient(160deg, #6e4b2c, #33200f 60%, #1a1007);
  border: 2px solid #d69a58;
  clip-path: polygon(50% 0, 96% 16%, 88% 72%, 50% 100%, 12% 72%, 4% 16%);
  display: flex; align-items: center; justify-content: center;
  box-shadow: inset 0 0 26px rgba(255,180,90,.28), 0 0 24px rgba(255,140,50,.16);
}
.rank-shield span { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 52px; color: #ffe3b8; text-shadow: 0 2px 0 #6e3b10; }
.rank-glow { position: absolute; inset: 0; background: radial-gradient(circle, rgba(255,140,40,.35), transparent 62%); filter: blur(6px); }
.rank-tier { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 26px; letter-spacing: 4px; color: #ffe4c2; }
.rank-points { font-size: 12px; letter-spacing: 2px; color: var(--muted); margin-bottom: 9px; }
.rank-points strong { color: #fff; font-size: 17px; }
.rank-progress { height: 6px; background: rgba(255,255,255,.08); overflow: hidden; clip-path: polygon(0 0,100% 0,99% 100%,0 100%); }
.rank-progress i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #c05a18, var(--orange-2)); transition: width .6s ease; }
.rank-next { display: flex; justify-content: space-between; gap: 6px; font-size: 9px; letter-spacing: 1px; color: var(--muted); margin-top: 6px; }
.rank-next b { color: #c7d1da; font-weight: 600; }
.lifetime-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin-top: 16px; border-top: 1px solid rgba(255,255,255,.09); padding-top: 12px; }
.lifetime-stats div { display: flex; flex-direction: column; gap: 2px; }
.lifetime-stats span { font-size: 8px; letter-spacing: 1.5px; color: var(--muted); }
.lifetime-stats strong { font-size: 20px; color: #fff; line-height: 1; }
.rank-note { margin-top: 14px; font-size: 8px; line-height: 1.5; letter-spacing: 1.2px; color: #66717e; }

.lobby-hero {
  align-self: center; display: flex; flex-direction: column; align-items: center;
  text-align: center; min-height: 0; max-height: 100%; overflow: auto; scrollbar-width: none;
  padding: 4px 0;
}
.lobby-hero::-webkit-scrollbar { display: none; }
.season-tag { display: flex; align-items: center; gap: 8px; font-size: 9px; letter-spacing: 3px; color: #c9d2db; font-weight: 600; }
.season-tag i { width: 5px; height: 5px; background: var(--orange); transform: rotate(45deg); box-shadow: 0 0 8px var(--orange); }
.game-title {
  margin: 6px 0 0; font-family: 'Bebas Neue', Impact, sans-serif; font-weight: 400;
  font-size: clamp(58px, 7.6vw, 112px); line-height: .82; letter-spacing: 3px; color: #fff;
  text-shadow: 0 4px 0 rgba(0,0,0,.35), 0 0 46px rgba(255,106,26,.2);
}
.game-title span { color: var(--orange); display: inline-block; transform: skewX(-4deg); }
.tagline { margin: 10px 0 12px; color: #c2ccd6; font-size: clamp(11px, 1.1vw, 14px); letter-spacing: 2.5px; text-transform: uppercase; }
.map-stats { display: flex; gap: 0; border-top: 1px solid rgba(255,255,255,.12); border-bottom: 1px solid rgba(255,255,255,.12); padding: 7px 0; }
.map-stats div { display: flex; flex-direction: column; align-items: center; padding: 0 clamp(12px, 1.7vw, 26px); border-right: 1px solid rgba(255,255,255,.09); }
.map-stats div:last-child { border-right: 0; }
.map-stats strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 23px; font-weight: 400; color: var(--orange-2); line-height: 1; }
.map-stats span { font-size: 8px; letter-spacing: 1.5px; color: var(--muted); margin-top: 2px; }
.poi-strip { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 7px; margin: 10px 0 4px; font-size: 8px; letter-spacing: 1.7px; color: #93a0ad; }
.poi-strip i { width: 3px; height: 3px; border-radius: 50%; background: rgba(255,106,26,.7); }

.loadout-section { width: 100%; margin-top: 6px; }
.section-head { display: flex; justify-content: space-between; align-items: flex-end; text-align: left; margin-bottom: 8px; gap: 12px; }
.section-head h3 { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 20px; letter-spacing: 1.5px; font-weight: 400; margin: 1px 0 0; }
.section-head small { color: #6e7b88; font-size: 8px; letter-spacing: 1.3px; max-width: 210px; text-align: right; }
.weapon-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; }
.weapon-card {
  position: relative; text-align: left; color: var(--text);
  background: linear-gradient(160deg, rgba(28,35,45,.88), rgba(10,13,18,.92));
  border: 1px solid rgba(255,255,255,.1); padding: 10px 11px 9px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%);
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
  overflow: hidden;
}
.weapon-card:hover { transform: translateY(-3px); border-color: rgba(255,150,60,.5); background: linear-gradient(160deg, rgba(42,33,24,.92), rgba(14,13,12,.94)); }
.weapon-card.selected { border-color: var(--orange); background: linear-gradient(160deg, rgba(67,38,17,.94), rgba(17,13,10,.95)); box-shadow: inset 0 0 24px rgba(255,106,26,.12); }
.weapon-card.selected::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--orange); box-shadow: 0 0 12px var(--orange); }
.weapon-tag { font-size: 7px; letter-spacing: 1.6px; color: var(--orange-2); font-weight: 700; }
.gun-icon { display: block; width: 100%; height: 36px; margin: 3px 0 1px; fill: #b7c3cd; filter: drop-shadow(0 2px 2px rgba(0,0,0,.5)); transition: fill .15s; }
.weapon-card.selected .gun-icon { fill: #ffe0bd; }
.weapon-card strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 25px; letter-spacing: 1.5px; font-weight: 400; line-height: 1; display: block; }
.weapon-role { display: block; color: #7f8c99; font-size: 8.5px; letter-spacing: .4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 1px 0 7px; }
.stat-bars { display: flex; flex-direction: column; gap: 2px; }
.stat-bars label { display: flex; align-items: center; gap: 5px; font-size: 7px; letter-spacing: 1px; color: #6f7c88; }
.stat-bars label i { flex: 1; height: 3px; background: rgba(255,255,255,.09); }
.stat-bars label b { display: block; height: 100%; background: linear-gradient(90deg, #b64b10, var(--orange-2)); }
.select-mark { display: none; position: absolute; right: 9px; top: 8px; font-size: 6.5px; letter-spacing: 1px; color: #1a0d03; background: var(--orange); padding: 2px 5px; font-weight: 700; }
.weapon-card.selected .select-mark { display: block; }

.deploy-btn {
  position: relative; margin-top: 12px; width: min(440px, 100%);
  border: 0; padding: 11px 34px 12px; color: #180a01;
  background: linear-gradient(100deg, #e95a10 0%, var(--orange) 34%, var(--orange-2) 68%, #ffd15c 100%);
  clip-path: polygon(4% 0, 100% 0, 96% 100%, 0 100%);
  box-shadow: 0 0 34px rgba(255,106,26,.35), inset 0 1px 0 rgba(255,255,255,.45);
  transition: transform .16s ease, box-shadow .16s ease;
  overflow: hidden;
}
.deploy-btn:hover { transform: scale(1.025); box-shadow: 0 0 52px rgba(255,120,30,.6), inset 0 1px 0 rgba(255,255,255,.55); }
.deploy-btn:active { transform: scale(.99); }
.deploy-main { display: block; font-family: 'Bebas Neue', Impact, sans-serif; font-size: clamp(28px, 3.1vw, 40px); line-height: .92; letter-spacing: 5px; }
.deploy-sub { display: block; font-size: 8.5px; letter-spacing: 2.2px; font-weight: 700; opacity: .72; margin-top: 2px; }
.deploy-shine { position: absolute; top: -50%; bottom: -50%; width: 22%; left: -40%; background: linear-gradient(90deg, transparent, rgba(255,255,255,.55), transparent); transform: skewX(-20deg); animation: deployShine 3.2s ease-in-out infinite; }
@keyframes deployShine { 0%, 62% { left: -40%; } 100% { left: 130%; } }
.deploy-note { margin-top: 6px; font-size: 8px; letter-spacing: 1.4px; color: #77838f; }

.settings-panel h2 { margin-bottom: 11px; }
.setting-row { display: block; margin-bottom: 13px; }
.setting-label { display: flex; align-items: center; justify-content: space-between; font-size: 9px; letter-spacing: 1.7px; color: #b3bec9; font-weight: 600; }
.setting-label b { color: var(--orange-2); font-size: 11px; letter-spacing: .5px; }
.setting-row input[type=range] {
  -webkit-appearance: none; appearance: none; width: 100%; height: 20px; background: transparent; margin: 1px 0 0;
}
.setting-row input[type=range]::-webkit-slider-runnable-track { height: 4px; background: linear-gradient(90deg, var(--orange), var(--orange-2)); opacity: .9; }
.setting-row input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none; width: 13px; height: 13px; margin-top: -4.5px; background: #fff;
  border: 2px solid var(--orange); transform: rotate(45deg); box-shadow: 0 0 10px rgba(255,106,26,.7);
}
.setting-row input[type=range]::-moz-range-track { height: 4px; background: linear-gradient(90deg, var(--orange), var(--orange-2)); }
.setting-row input[type=range]::-moz-range-thumb { width: 10px; height: 10px; background: #fff; border: 2px solid var(--orange); border-radius: 0; transform: rotate(45deg); }
.setting-row small { display: block; font-size: 8.5px; letter-spacing: .7px; color: #677481; margin-top: -1px; }
.select-row select {
  width: 100%; margin-top: 4px; background: #121821; border: 1px solid rgba(255,255,255,.16);
  color: #dfe7ee; font-size: 10px; letter-spacing: 1px; padding: 7px 8px; outline: none;
}
.toggle-row { display: flex; align-items: center; justify-content: space-between; font-size: 9px; letter-spacing: 1.6px; color: #b3bec9; font-weight: 600; margin: 2px 0 14px; cursor: pointer; }
.toggle-row input { display: none; }
.toggle-row i { width: 34px; height: 17px; background: rgba(255,255,255,.12); position: relative; transition: .2s; clip-path: polygon(6% 0,100% 0,94% 100%,0 100%); }
.toggle-row i::after { content: ''; position: absolute; width: 11px; height: 11px; left: 3px; top: 3px; background: #8b96a2; transition: .2s; }
.toggle-row input:checked + i { background: rgba(255,106,26,.55); }
.toggle-row input:checked + i::after { left: 19px; background: #fff; box-shadow: 0 0 8px #fff; }
.guide-box { border-top: 1px solid rgba(255,255,255,.09); padding-top: 12px; }
.guide-box h4 { margin: 0 0 4px; font-size: 9px; letter-spacing: 2px; color: var(--orange); }
.guide-box p { margin: 0 0 9px; color: #8996a3; font-size: 9.5px; line-height: 1.5; letter-spacing: .3px; }
.guide-keys { display: flex; align-items: center; flex-wrap: wrap; gap: 4px; font-size: 7.5px; letter-spacing: 1px; color: #788592; }
.lobby-footer-links { display: flex; gap: 6px; justify-content: center; margin-top: 12px; font-size: 7.5px; letter-spacing: 1.5px; color: #56616d; }

/* ============================================================
   HUD
   ============================================================ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top-left { position: absolute; top: calc(14px + var(--safe-t)); left: calc(16px + var(--safe-l)); display: flex; flex-direction: column; gap: 7px; }
.minimap-shell {
  position: relative; width: 172px; height: 172px;
  background: rgba(6,10,14,.72); border: 1px solid rgba(255,255,255,.2);
  box-shadow: 0 0 0 3px rgba(0,0,0,.25), inset 0 0 24px rgba(0,0,0,.55);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  overflow: hidden;
}
#minimap { width: 100%; height: 100%; display: block; opacity: .96; }
.minimap-ring { position: absolute; inset: 0; pointer-events: none; border: 1px solid rgba(255,106,26,.35); }
.minimap-compass { position: absolute; top: 4px; left: 50%; transform: translateX(-50%); font-size: 9px; font-weight: 700; color: var(--orange-2); text-shadow: 0 1px 3px #000; letter-spacing: 1px; }
.zone-chip {
  display: flex; align-items: center; justify-content: space-between; width: 172px;
  background: rgba(8,12,17,.78); border-left: 2px solid var(--cyan); padding: 5px 8px;
  clip-path: polygon(0 0,100% 0,96% 100%,0 100%);
}
.zone-chip span { font-size: 8px; letter-spacing: 1.7px; color: #9fadb9; }
.zone-chip strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 18px; letter-spacing: 1.5px; color: #dff6ff; font-weight: 400; }
.zone-chip.warn { border-left-color: var(--red); animation: chipWarn 1s infinite; }
@keyframes chipWarn { 50% { background: rgba(70,10,10,.8); } }
.fps-meter { font-size: 8px; color: #5d6a76; letter-spacing: 1px; }

.hud-top-center { position: absolute; top: calc(12px + var(--safe-t)); left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 4px; }
.match-info { display: flex; align-items: center; gap: 10px; padding: 4px 14px; background: rgba(7,11,15,.66); border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.08); clip-path: polygon(4% 0,100% 0,96% 100%,0 100%); }
.info-block { display: flex; align-items: baseline; gap: 4px; font-size: 8px; letter-spacing: 1.6px; color: #9aa7b3; }
.info-block b { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 21px; font-weight: 400; color: #fff; letter-spacing: 1px; }
.match-info .sep { width: 1px; height: 14px; background: rgba(255,255,255,.14); }
.map-chip { color: var(--orange-2); font-weight: 700; }
.compass-wrap { position: relative; width: 300px; height: 23px; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent); }
.compass-strip { position: absolute; top: 2px; left: 0; height: 100%; white-space: nowrap; font-size: 9px; letter-spacing: 1px; color: #aab7c3; font-weight: 600; }
.compass-strip span { display: inline-block; width: 60px; text-align: center; }
.compass-strip span.major { color: #fff; font-size: 11px; }
.compass-pointer { position: absolute; top: 0; left: 50%; width: 0; height: 0; transform: translateX(-50%); border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 6px solid var(--orange); }

.hud-top-right { position: absolute; top: calc(14px + var(--safe-t)); right: calc(16px + var(--safe-r)); width: min(330px, 32vw); display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.killfeed { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; width: 100%; }
.kill-item { display: flex; align-items: center; gap: 7px; background: rgba(5,8,12,.74); border-right: 2px solid rgba(255,255,255,.25); padding: 3px 8px; font-size: 9px; letter-spacing: .7px; color: #c8d3dc; animation: killIn .25s ease-out; clip-path: polygon(4% 0,100% 0,100% 100%,0 100%); }
.kill-item .k-killer { color: #e8eef3; font-weight: 600; }
.kill-item .k-victim { color: #9daab6; }
.kill-item .k-weapon { color: var(--orange-2); font-size: 8px; letter-spacing: 1px; }
.kill-item.me { border-right-color: var(--orange); background: rgba(45,20,5,.8); }
.kill-item.head { border-right-color: var(--red); }
@keyframes killIn { from { transform: translateX(22px); opacity: 0; } }

.crosshair { position: absolute; left: 50%; top: 50%; width: 0; height: 0; z-index: 3; }
.ch { position: absolute; background: #f3fbff; box-shadow: 0 0 2px #000, 0 0 5px rgba(0,0,0,.8); }
.ch-t, .ch-b { width: 2px; height: var(--ch-len); left: -1px; }
.ch-t { bottom: var(--gap); }
.ch-b { top: var(--gap); }
.ch-l, .ch-r { height: 2px; width: var(--ch-len); top: -1px; }
.ch-l { right: var(--gap); }
.ch-r { left: var(--gap); }
.ch-dot { position: absolute; width: 3px; height: 3px; left: -1.5px; top: -1.5px; border-radius: 50%; background: #fff; box-shadow: 0 0 4px #000; }
.crosshair.enemy .ch { background: #ff5a4a; }
.crosshair.hide { opacity: 0; }

.hitmarker { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%,-50%) scale(.7); opacity: 0; z-index: 4; }
.hitmarker i { position: absolute; width: 2px; height: 8px; background: #fff; left: 12px; top: 9px; box-shadow: 0 0 4px rgba(0,0,0,.8); }
.hitmarker i:nth-child(1) { transform: rotate(45deg) translateY(-9px); }
.hitmarker i:nth-child(2) { transform: rotate(135deg) translateY(-9px); }
.hitmarker i:nth-child(3) { transform: rotate(225deg) translateY(-9px); }
.hitmarker i:nth-child(4) { transform: rotate(315deg) translateY(-9px); }
.hitmarker.show { animation: hitPop .28s ease-out; }
.hitmarker.kill i { background: #ff4d3d; }
@keyframes hitPop { 0% { opacity: 1; transform: translate(-50%,-50%) scale(1.25); } 100% { opacity: 0; transform: translate(-50%,-50%) scale(.9); } }

#damage-numbers { position: absolute; inset: 0; pointer-events: none; z-index: 5; overflow: hidden; }
.dmg-num { position: absolute; font-family: 'Bebas Neue', Impact, sans-serif; font-size: 22px; color: #fff; text-shadow: 0 2px 4px #000, 0 0 10px rgba(0,0,0,.8); transform: translate(-50%,-50%); animation: dmgFloat .75s ease-out forwards; white-space: nowrap; }
.dmg-num.head { color: var(--yellow); font-size: 28px; }
@keyframes dmgFloat { 0% { opacity: 1; margin-top: 0; } 100% { opacity: 0; margin-top: -38px; } }

.pickup-prompt {
  position: absolute; left: 50%; top: 62%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px; padding: 6px 14px 6px 8px;
  background: rgba(6,10,14,.82); border: 1px solid rgba(255,255,255,.18); border-left: 2px solid var(--orange);
  clip-path: polygon(0 0,100% 0,97% 100%,0 100%);
}
.pickup-prompt kbd { background: var(--orange); color: #160a02; border: 0; }
.pickup-prompt span { font-size: 9px; letter-spacing: 1.5px; color: #b7c2cc; }
.pickup-prompt strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 19px; font-weight: 400; letter-spacing: 1.5px; color: #fff; }
.pickup-prompt small { font-size: 7px; letter-spacing: 1.3px; color: var(--orange-2); }

.banner { position: absolute; left: 50%; top: 22%; transform: translateX(-50%); text-align: center; z-index: 6; pointer-events: none; }
.banner span { display: block; font-size: 9px; letter-spacing: 4px; color: var(--orange-2); margin-bottom: 2px; }
.banner strong { display: block; font-family: 'Bebas Neue', Impact, sans-serif; font-size: clamp(30px, 4.3vw, 58px); letter-spacing: 4px; font-weight: 400; line-height: .95; color: #fff; text-shadow: 0 4px 18px rgba(0,0,0,.7), 0 0 30px rgba(255,106,26,.25); }
.banner.show { animation: bannerIn .4s ease-out; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, 12px) scale(.96); } }

.storm-warning { position: absolute; left: 50%; top: 34%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; background: rgba(60,8,8,.86); border: 1px solid rgba(255,70,70,.5); padding: 7px 16px; clip-path: polygon(3% 0,100% 0,97% 100%,0 100%); animation: stormPulse 1.2s infinite; }
.storm-icon { width: 24px; height: 24px; border-radius: 50%; background: var(--red); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 15px; }
.storm-warning div { display: flex; flex-direction: column; }
.storm-warning strong { font-size: 10px; letter-spacing: 2px; color: #ffd6d6; }
.storm-warning small { font-size: 7.5px; letter-spacing: 1.2px; color: #e6a5a5; }
@keyframes stormPulse { 50% { box-shadow: 0 0 26px rgba(255,50,50,.4); } }

.hud-bottom-left { position: absolute; left: calc(16px + var(--safe-l)); bottom: calc(16px + var(--safe-b)); }
.health-card { width: 276px; background: linear-gradient(100deg, rgba(5,9,13,.86), rgba(9,14,20,.66)); border-left: 2px solid var(--green); padding: 8px 10px 7px; clip-path: polygon(0 0,100% 0,97% 100%,0 100%); }
.health-row { display: flex; align-items: baseline; gap: 5px; }
.health-label { font-size: 8px; letter-spacing: 2px; color: #93a1ad; margin-right: auto; }
.health-row strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 30px; line-height: .9; font-weight: 400; color: #fff; }
.health-row small { font-size: 9px; color: #72808c; letter-spacing: 1px; }
.armor-chip { font-size: 7px; letter-spacing: 1px; color: var(--cyan); border: 1px solid rgba(58,216,255,.4); padding: 1px 4px; }
.health-bar { position: relative; height: 9px; background: rgba(255,255,255,.09); margin: 3px 0 4px; overflow: hidden; }
.health-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #3bbf4a, #7ef06a); transition: width .18s ease; box-shadow: 0 0 10px rgba(110,230,106,.35); }
.health-fill.warn { background: linear-gradient(90deg, #c98a10, #ffd23f); }
.health-fill.crit { background: linear-gradient(90deg, #c51d1d, #ff4d3d); }
.health-ticks { position: absolute; inset: 0; background-image: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0,0,0,.45) calc(10% - 1px) 10%); }
.health-shine { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(255,255,255,.28), transparent 45%); }
.heal-row { display: flex; align-items: center; gap: 5px; font-size: 8px; letter-spacing: 1.4px; color: #84919d; }
.heal-row b { color: #fff; font-size: 11px; margin-left: 1px; }
.heal-progress { position: relative; flex: 1; height: 3px; background: rgba(255,255,255,.1); margin-left: 6px; }
.heal-progress i { display: block; height: 100%; width: 0%; background: var(--green); }

.hud-bottom-center { position: absolute; left: 50%; bottom: calc(16px + var(--safe-b)); transform: translateX(-50%); text-align: center; }
.weapon-hud { min-width: 260px; padding: 5px 18px 7px; background: linear-gradient(180deg, rgba(5,9,13,.32), rgba(5,9,13,.82)); border-bottom: 2px solid rgba(255,106,26,.65); clip-path: polygon(6% 0,94% 0,100% 100%,0 100%); }
.weapon-cat { font-size: 7.5px; letter-spacing: 2.4px; color: var(--orange-2); }
.weapon-name { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 27px; line-height: .95; letter-spacing: 2px; color: #fff; }
.ammo-row { display: flex; align-items: baseline; justify-content: center; gap: 4px; line-height: 1; margin-top: -2px; }
.ammo-row strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 30px; font-weight: 400; color: #fff; }
.ammo-row .slash { color: #5d6b78; font-size: 16px; }
.ammo-row small { font-size: 15px; color: #9aa7b2; font-weight: 600; }
.ammo-row strong.empty { color: var(--red); animation: emptyPulse .6s infinite; }
@keyframes emptyPulse { 50% { opacity: .4 } }
.weapon-slots { display: flex; justify-content: center; gap: 4px; margin-top: 4px; }
.wslot { display: flex; align-items: center; gap: 4px; padding: 1px 6px; border: 1px solid rgba(255,255,255,.13); background: rgba(255,255,255,.04); font-size: 7.5px; letter-spacing: 1px; color: #7f8c98; }
.wslot.active { border-color: var(--orange); color: #ffe0c0; background: rgba(255,106,26,.14); }
.wslot b { color: #fff; font-size: 8px; }
.reload-bar { position: relative; height: 4px; margin-top: 4px; background: rgba(255,255,255,.1); overflow: hidden; }
.reload-bar i { display: block; height: 100%; width: 0%; background: var(--orange-2); }
.reload-bar span { position: absolute; inset: 0; font-size: 6px; letter-spacing: 2px; color: #fff; text-align: center; line-height: 4px; }

.hud-bottom-right { position: absolute; right: calc(16px + var(--safe-r)); bottom: calc(16px + var(--safe-b)); }
.controls-hint { display: grid; grid-template-columns: auto auto; gap: 3px 12px; font-size: 7.5px; letter-spacing: 1px; color: #7d8a96; text-align: right; }
.controls-hint div { display: flex; align-items: center; justify-content: flex-end; gap: 5px; }
.controls-hint kbd { height: 15px; font-size: 8px; min-width: 17px; }

.scope-overlay { position: absolute; inset: 0; z-index: 8; pointer-events: none; background: radial-gradient(circle at center, transparent 0 32vmin, rgba(0,0,0,.975) 32.4vmin); }
.scope-lens { position: absolute; left: 50%; top: 50%; width: 64vmin; height: 64vmin; transform: translate(-50%,-50%); border-radius: 50%; border: 2px solid rgba(0,0,0,.9); box-shadow: inset 0 0 60px rgba(0,0,0,.7), inset 0 0 10px rgba(0,0,0,.5); }
.scope-line { position: absolute; background: rgba(10,10,10,.85); }
.scope-h { left: calc(50% - 32vmin); width: 64vmin; height: 1px; top: 50%; }
.scope-v { top: calc(50% - 32vmin); height: 64vmin; width: 1px; left: 50%; }
.scope-mildots { position: absolute; left: 50%; top: 50%; width: 2px; height: 2px; }
.scope-mildots::before, .scope-mildots::after { content: ''; position: absolute; left: -1px; width: 4px; height: 4px; border-radius: 50%; background: rgba(10,10,10,.85); }
.scope-mildots::before { top: 6vmin; box-shadow: 0 3vmin 0 rgba(10,10,10,.85), 0 6vmin 0 rgba(10,10,10,.85); }
.scope-mildots::after { top: -6vmin; box-shadow: 0 -3vmin 0 rgba(10,10,10,.85), 0 -6vmin 0 rgba(10,10,10,.85); }
.scope-info { position: absolute; bottom: 5vmin; left: 50%; transform: translateX(-50%); font-size: 9px; letter-spacing: 3px; color: #c8d2db; }
.scope-range { position: absolute; left: calc(50% + 6vmin); top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 3vmin; font-size: 7px; color: #9aa6b2; }
.scope-range span { border-left: 5px solid #9aa6b2; padding-left: 4px; }

/* ============================================================
   TOUCH CONTROLS
   ============================================================ */
.mobile-controls { position: absolute; inset: 0; pointer-events: none; z-index: 9; }
.move-zone {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(18px + var(--safe-b));
  width: 132px; height: 132px; border-radius: 50%;
  background: rgba(8,12,17,.34); border: 1px solid rgba(255,255,255,.18);
  pointer-events: auto; touch-action: none;
}
.move-ring { position: absolute; inset: 22px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.18); }
.move-knob {
  position: absolute; left: 50%; top: 50%; width: 50px; height: 50px; margin: -25px 0 0 -25px;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.6), rgba(255,106,26,.65));
  border: 1px solid rgba(255,255,255,.55); box-shadow: 0 0 18px rgba(255,106,26,.4);
}
.move-label { position: absolute; bottom: -15px; left: 50%; transform: translateX(-50%); font-size: 7px; letter-spacing: 2px; color: rgba(255,255,255,.4); }
.look-zone { position: absolute; right: 0; top: 0; width: 58%; height: 100%; pointer-events: auto; touch-action: none; }
.mbtn {
  position: absolute; pointer-events: auto; touch-action: none; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.3); background: rgba(8,12,17,.42);
  color: #eaf2f8; font-family: 'Rajdhani', sans-serif; font-weight: 700; letter-spacing: 1px;
  display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(3px); transition: background .1s, transform .1s;
}
.mbtn:active, .mbtn.active { background: rgba(255,106,26,.6); transform: scale(.94); border-color: #fff; }
.mbtn-fire { right: calc(22px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); width: 92px; height: 92px; font-size: 13px; border: 2px solid rgba(255,140,60,.75); background: radial-gradient(circle at 35% 30%, rgba(255,150,60,.35), rgba(8,12,17,.5)); box-shadow: 0 0 26px rgba(255,106,26,.22); }
.mbtn-ads { right: calc(122px + var(--safe-r)); bottom: calc(42px + var(--safe-b)); width: 66px; height: 66px; font-size: 11px; }
.mbtn-small { width: 46px; height: 46px; font-size: 9px; }
.btn-reload { right: calc(30px + var(--safe-r)); bottom: calc(124px + var(--safe-b)); }
.btn-jump { right: calc(88px + var(--safe-r)); bottom: calc(118px + var(--safe-b)); }
.btn-crouch { right: calc(148px + var(--safe-r)); bottom: calc(102px + var(--safe-b)); }
.btn-heal { right: calc(22px + var(--safe-r)); bottom: calc(180px + var(--safe-b)); }
.btn-pickup { right: calc(76px + var(--safe-r)); bottom: calc(174px + var(--safe-b)); border-color: rgba(255,200,80,.6); }
.btn-swap { right: calc(130px + var(--safe-r)); bottom: calc(160px + var(--safe-b)); font-size: 7px; }

/* ============================================================
   MODALS / RESULTS
   ============================================================ */
.modal { position: absolute; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center; background: rgba(3,5,8,.7); backdrop-filter: blur(8px); }
.modal-card { width: min(720px, 92vw); background: linear-gradient(160deg, rgba(18,23,31,.98), rgba(7,10,14,.98)); border: 1px solid rgba(255,255,255,.14); border-top: 2px solid var(--orange); padding: 24px 28px 22px; clip-path: polygon(0 0,100% 0,100% calc(100% - 20px), calc(100% - 20px) 100%,0 100%); box-shadow: 0 40px 100px rgba(0,0,0,.65); }
.modal-card h2 { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 46px; font-weight: 400; letter-spacing: 4px; margin: 0 0 16px; }
.pause-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 30px; }
.pause-grid h3 { font-size: 10px; letter-spacing: 2.5px; color: var(--orange); margin: 0 0 10px; }
.setting-row.compact { margin-bottom: 11px; }
.pause-stats { border-left: 1px solid rgba(255,255,255,.1); padding-left: 24px; }
.pause-stats > div { display: flex; justify-content: space-between; align-items: baseline; padding: 5px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 9px; letter-spacing: 1.5px; color: #8e9aa6; }
.pause-stats > div strong { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 21px; font-weight: 400; color: #fff; }
.pause-stats .pause-tip { display: block; border: 0; font-size: 8px; line-height: 1.5; color: #6d7a86; margin-top: 12px; padding: 0; }
.toggle-row.compact-toggle { margin-top: 12px; }
.modal-actions { display: flex; gap: 10px; margin-top: 20px; }
.primary-btn {
  border: 0; background: linear-gradient(100deg, #e95a10, var(--orange) 55%, var(--orange-2));
  color: #190a01; font-weight: 700; font-size: 12px; letter-spacing: 2px; padding: 12px 24px;
  clip-path: polygon(5% 0,100% 0,95% 100%,0 100%); transition: .15s;
}
.primary-btn:hover { filter: brightness(1.12); transform: translateY(-1px); }
.modal-actions .ghost-btn { padding: 12px 20px; }

.results-screen { z-index: 55; display: flex; align-items: center; justify-content: center; }
.results-bg { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(255,106,26,.16), transparent 55%), rgba(3,5,8,.72); backdrop-filter: blur(9px); }
.results-card { position: relative; width: min(560px, 92vw); text-align: center; padding: 28px 34px 26px; background: linear-gradient(165deg, rgba(20,25,33,.97), rgba(7,10,14,.98)); border: 1px solid rgba(255,255,255,.14); border-top: 2px solid var(--orange); clip-path: polygon(0 0,100% 0,100% calc(100% - 24px), calc(100% - 24px) 100%,0 100%); box-shadow: 0 40px 120px rgba(0,0,0,.7); animation: resultIn .45s cubic-bezier(.2,.9,.3,1.1); }
@keyframes resultIn { from { opacity: 0; transform: translateY(22px) scale(.97); } }
.results-card h2 { font-family: 'Bebas Neue', Impact, sans-serif; font-size: 68px; line-height: .85; letter-spacing: 6px; margin: 3px 0 4px; font-weight: 400; color: #fff; text-shadow: 0 0 34px rgba(255,106,26,.45); }
.results-card h2.lost { color: #ff8a80; text-shadow: 0 0 34px rgba(255,60,50,.35); }
