+    p.adsBlend = lerp(p.adsBlend, p.ads ? 1 : 0, 1 - Math.exp(-13 * dt));
+    p.recoilPitch *= Math.exp(-8 * dt);
+    p.recoilYaw *= Math.exp(-8 * dt);
+    p.viewKick *= Math.exp(-10 * dt);
