import * as THREE from '../vendor/three.module.js';
import { WEAPONS } from './weapons.js';

const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const rand = (a, b) => a + Math.random() * (b - a);

const NAMES = [
  'RAVEN', 'NOVA', 'GHOST', 'KIRA', 'BLAZE', 'VIPER', 'ROOK', 'ECHO',
  'SABLE', 'FURY', 'ONYX', 'LYNX', 'HAVOC', 'ZERO', 'MIRAGE', 'TALON',
  'RIFT', 'SPECTER', 'JINX', 'ACE', 'WRAITH', 'CIPHER', 'BOLT', 'DUSK'
];
const COLORS = [0x9d3c2f, 0x2f6d9d, 0x7a6a2f, 0x3c7a4a, 0x7a3c76, 0x59616a, 0x9a5a2a, 0x2f7a7a];

function angleLerp(a, b, t) {
  let d = (b - a + Math.PI) % (Math.PI * 2) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

export class BotManager {
  constructor(game) {
    this.game = game;
    this.world = game.world;
    this.scene = game.scene;
    this.player = game.player;
    this.ui = game.ui;
    this.audio = game.audio;
    this.effects = game.effects;
    this.bots = [];
    this.hitMeshes = [];
  }

  spawn(count = 23) {
    const spawns = this.world.botSpawns;
    const names = [...NAMES].sort(() => Math.random() - 0.5);
    for (let i = 0; i < count; i++) {
      const sp = spawns[i % Math.max(1, spawns.length)] || { x: rand(-300, 300), z: rand(-300, 300) };
      const x = clamp(sp.x + rand(-7, 7), -480, 480);
      const z = clamp(sp.z + rand(-7, 7), -480, 480);
      const y = this.world.groundHeight(x, z, Infinity);
      const roll = Math.random();
      const weaponId = roll < 0.52 ? 'ak47' : roll < 0.82 ? 'ump' : 'awm';
      const bot = {
        id: i, name: names[i % names.length],
        pos: new THREE.Vector3(x, y, z),
        yaw: rand(-Math.PI, Math.PI),
        health: 100, maxHealth: 100, alive: true,
        weaponId, def: WEAPONS[weaponId],
        fireTimer: rand(1.2, 3.5), think: rand(0, 0.6),
        target: null, targetType: null,
        wander: new THREE.Vector3(x, y, z),
        mesh: null, hpGroup: null, hpFill: null,
        hitMeshes: [], legL: null, legR: null, armL: null, armR: null,
        walk: Math.random() * 6, deadTimer: 0, kills: 0,
        skill: rand(0.75, 1.18), stormTick: 0,
        stuck: 0, lastX: x, lastZ: z, strafe: Math.random() > 0.5 ? 1 : -1
      };
      this._buildMesh(bot);
      this.bots.push(bot);
      this.hitMeshes.push(...bot.hitMeshes);
    }
  }

  _buildMesh(bot) {
    const group = new THREE.Group();
    group.position.copy(bot.pos);
    group.rotation.y = bot.yaw;
    const bodyMat = new THREE.MeshStandardMaterial({ color: COLORS[bot.id % COLORS.length], roughness: 0.78, metalness: 0.04 });
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x252b30, roughness: 0.7, metalness: 0.18 });
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xb9855f, roughness: 0.9 });
    const accentMat = new THREE.MeshStandardMaterial({ color: 0xd6a02e, roughness: 0.6, metalness: 0.2 });

    const add = (parent, w, h, d, mat, x, y, z, head = false) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      m.position.set(x, y, z);
      m.castShadow = this.world.quality === 'high';
      m.userData.bot = bot;
      if (head) m.userData.isHead = true;
      parent.add(m);
      bot.hitMeshes.push(m);
      return m;
    };

    add(group, 0.56, 0.62, 0.34, bodyMat, 0, 1.23, 0);
    add(group, 0.58, 0.12, 0.36, accentMat, 0, 1.18, 0);
    add(group, 0.34, 0.34, 0.32, skinMat, 0, 1.72, 0, true);
    add(group, 0.38, 0.14, 0.36, darkMat, 0, 1.9, 0);
    add(group, 0.4, 0.4, 0.18, darkMat, 0, 1.22, 0.23);

    const legL = new THREE.Group();
    legL.position.set(-0.16, 0.9, 0);
    add(legL, 0.21, 0.74, 0.23, darkMat, 0, -0.36, 0);
    add(legL, 0.24, 0.14, 0.3, darkMat, 0, -0.76, -0.03);
    group.add(legL);
    const legR = new THREE.Group();
    legR.position.set(0.16, 0.9, 0);
    add(legR, 0.21, 0.74, 0.23, darkMat, 0, -0.36, 0);
    add(legR, 0.24, 0.14, 0.3, darkMat, 0, -0.76, -0.03);
    group.add(legR);

    const armL = new THREE.Group();
    armL.position.set(-0.38, 1.45, 0);
    add(armL, 0.15, 0.5, 0.17, bodyMat, 0, -0.23, 0);
    group.add(armL);
    const armR = new THREE.Group();
    armR.position.set(0.38, 1.45, 0);
    add(armR, 0.15, 0.5, 0.17, bodyMat, 0, -0.23, 0);
    group.add(armR);

    // Simple rifle silhouette in the bot's hands.
    add(group, 0.09, 0.1, 0.62, darkMat, 0.27, 1.27, -0.32);
    add(group, 0.05, 0.05, 0.3, accentMat, 0.27, 1.28, -0.72);
    add(group, 0.08, 0.14, 0.09, darkMat, 0.27, 1.14, -0.2);

    this.game.matchGroup.add(group);
    bot.mesh = group;
    bot.legL = legL; bot.legR = legR; bot.armL = armL; bot.armR = armR;

    const hp = new THREE.Group();
    const bg = new THREE.Mesh(
      new THREE.PlaneGeometry(1.02, 0.13),
      new THREE.MeshBasicMaterial({ color: 0x0a0b0d, transparent: true, opacity: 0.72, depthWrite: false })
    );
    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(0.92, 0.075),
      new THREE.MeshBasicMaterial({ color: 0x6ee66a, depthWrite: false })
    );
    fill.position.z = 0.002;
    hp.add(bg, fill);
    hp.position.set(bot.pos.x, bot.pos.y + 2.22, bot.pos.z);
    hp.visible = false;
    hp.renderOrder = 20;
    this.game.matchGroup.add(hp);
    bot.hpGroup = hp;
    bot.hpFill = fill;
    bot.hpBg = bg;
  }

  aliveCount() {
    let n = 0;
    for (const b of this.bots) if (b.alive) n++;
    return n;
  }

  damageBot(bot, damage, head, point, weaponName) {
    if (!bot || !bot.alive) return;
    bot.health -= damage;
    bot.lastHurt = this.game.time;
    if (bot.health <= 0) {
      this.killBot(bot, this.game.player, weaponName, head);
    }
  }

  killBot(bot, killer, weaponName, head = false) {
    if (!bot.alive) return;
    bot.alive = false;
    bot.health = 0;
    bot.deadTimer = 0;
    if (bot.hpGroup) bot.hpGroup.visible = false;
    for (const m of bot.hitMeshes) {
      const idx = this.hitMeshes.indexOf(m);
      if (idx >= 0) this.hitMeshes.splice(idx, 1);
    }
    bot.hitMeshes = [];
    const byPlayer = killer === this.game.player;
    let killerName = 'STORM';
    if (killer === this.game.player) killerName = 'YOU';
    else if (killer && killer.name) { killerName = killer.name; killer.kills += 1; }

    this.effects.spawn(new THREE.Vector3(bot.pos.x, bot.pos.y + 1.2, bot.pos.z), 0xb51f1f, 16, 4.5, 11, 0.7);
    this.ui.addKill(killerName, bot.name, weaponName, { me: byPlayer, head });
    if (byPlayer) {
      this.player.p.kills += 1;
      this.audio.kill();
      this.ui.showHitmarker(true, head);
      this.ui.showBanner('ELIMINATED', bot.name, 800);
    }

    this.game.spawnLootAt(bot.pos.x + rand(-1, 1), bot.pos.z + rand(-1, 1), 'weapon', bot.weaponId, 0.4);
    if (Math.random() < 0.55) {
      this.game.spawnLootAt(bot.pos.x + rand(-1.5, 1.5), bot.pos.z + rand(-1.5, 1.5), 'medkit', null, 0.4);
    }
    this.game.checkVictory();
  }

  update(dt) {
    const player = this.player.p;
    const zone = this.game.zone;
    for (const bot of this.bots) {
      if (!bot.alive) {
        bot.deadTimer += dt;
        if (bot.mesh) {
          if (bot.deadTimer < 0.55) {
            const t = bot.deadTimer / 0.55;
            bot.mesh.rotation.z = t * Math.PI * 0.5;
            bot.mesh.position.y = bot.pos.y + Math.sin(t * Math.PI) * 0.12;
          } else {
            bot.mesh.position.y -= dt * 0.22;
            bot.mesh.rotation.z = Math.PI * 0.5;
          }
          if (bot.deadTimer > 7) {
            bot.mesh.visible = false;
            if (bot.hpGroup) bot.hpGroup.visible = false;
          }
        }
        continue;
      }

      const ground = this.world.groundHeight(bot.pos.x, bot.pos.z, bot.pos.y);
      bot.pos.y = ground < 0.1 && bot.pos.y < 1.4 ? Math.max(ground, -0.85) : ground;
      if (Math.hypot(bot.pos.x - bot.lastX, bot.pos.z - bot.lastZ) < 0.05) bot.stuck += dt;
      else { bot.stuck = 0; bot.lastX = bot.pos.x; bot.lastZ = bot.pos.z; }

      const dz = Math.hypot(bot.pos.x - zone.x, bot.pos.z - zone.z);
      const outside = dz > zone.radius;
      if (outside) {
        bot.stormTick += dt;
        if (bot.stormTick > 1) {
          bot.stormTick = 0;
          bot.health -= zone.damage;
          if (bot.health <= 0) { this.killBot(bot, null, 'ZONE'); continue; }
        }
      } else bot.stormTick = 0;

      bot.think -= dt;
      if (bot.think <= 0) {
        bot.think = rand(0.6, 1.15);
        this._think(bot, outside);
      }

      this._move(bot, dt, outside);

      // Shooting
      if (bot.target) {
        const targetPos = bot.targetType === 'player' ? player.pos : bot.target.pos;
        const dist = Math.hypot(targetPos.x - bot.pos.x, targetPos.z - bot.pos.z);
        if (bot.fireTimer > 0) bot.fireTimer -= dt;
        if (bot.fireTimer <= 0 && dist < (bot.weaponId === 'awm' ? 170 : 90)) {
          if (this.world.hasLineOfSight(bot.pos.x, bot.pos.y + 1.3, bot.pos.z, targetPos.x, targetPos.y + 1.2, targetPos.z)) {
            this._shoot(bot, targetPos, dist);
            const rpm = bot.weaponId === 'awm' ? 52 : bot.def.rpm * 0.62;
            bot.fireTimer = (60 / rpm) * rand(1.4, 2.2);
          }
        }
      }

      if (bot.mesh) {
        bot.mesh.position.set(bot.pos.x, bot.pos.y, bot.pos.z);
        bot.mesh.rotation.y = bot.yaw;
        const moving = Math.hypot(bot.pos.x - bot.lastX, bot.pos.z - bot.lastZ) > 0.01;
        if (moving) bot.walk += dt * 7;
        const swing = moving ? Math.sin(bot.walk) * 0.55 : 0;
        if (bot.legL) bot.legL.rotation.x = swing;
        if (bot.legR) bot.legR.rotation.x = -swing;
        if (bot.armL) bot.armL.rotation.x = -swing * 0.35;
        if (bot.armR) bot.armR.rotation.x = swing * 0.35;
      }
      if (bot.hpGroup) {
        const d = Math.hypot(bot.pos.x - player.pos.x, bot.pos.z - player.pos.z);
        bot.hpGroup.visible = d < 120;
        if (bot.hpGroup.visible) {
          bot.hpGroup.position.set(bot.pos.x, bot.pos.y + 2.22, bot.pos.z);
          bot.hpGroup.quaternion.copy(this.game.camera.quaternion);
          const f = clamp(bot.health / bot.maxHealth, 0, 1);
          bot.hpFill.scale.x = f;
          bot.hpFill.position.x = -(1 - f) * 0.46;
          bot.hpFill.material.color.setHex(f > 0.55 ? 0x6ee66a : f > 0.28 ? 0xffd23f : 0xff3d3d);
        }
      }
    }
  }

  _think(bot, outside) {
    const player = this.player.p;
    const zone = this.game.zone;
    if (outside) {
      bot.target = null;
      bot.targetType = null;
      bot.wander.set(zone.x + rand(-zone.radius * 0.35, zone.radius * 0.35), 0, zone.z + rand(-zone.radius * 0.35, zone.radius * 0.35));
      return;
    }
    const pd = Math.hypot(player.pos.x - bot.pos.x, player.pos.z - bot.pos.z);
    if (player.alive && !player.dropping && pd < 105) {
      if (this.world.hasLineOfSight(bot.pos.x, bot.pos.y + 1.3, bot.pos.z, player.pos.x, player.pos.y + 1.2, player.pos.z)) {
        bot.target = player;
        bot.targetType = 'player';
        bot.strafe = Math.random() > 0.5 ? 1 : -1;
        return;
      }
    }
    let best = null, bestD = 82;
    for (const other of this.bots) {
      if (other === bot || !other.alive) continue;
      const d = Math.hypot(other.pos.x - bot.pos.x, other.pos.z - bot.pos.z);
      if (d < bestD) {
        if (this.world.hasLineOfSight(bot.pos.x, bot.pos.y + 1.3, bot.pos.z, other.pos.x, other.pos.y + 1.2, other.pos.z)) {
          best = other; bestD = d;
        }
      }
    }
    if (best) {
      bot.target = best; bot.targetType = 'bot';
      return;
    }
    bot.target = null; bot.targetType = null;
    const r = zone.radius * 0.55;
    bot.wander.set(zone.x + rand(-r, r), 0, zone.z + rand(-r, r));
  }

  _move(bot, dt, outside) {
    let tx, tz, speed;
    if (bot.target) {
      const t = bot.targetType === 'player' ? this.player.p.pos : bot.target.pos;
      const dist = Math.hypot(t.x - bot.pos.x, t.z - bot.pos.z);
      const desired = bot.weaponId === 'awm' ? 58 : bot.weaponId === 'ump' ? 17 : 28;
      const dx = (t.x - bot.pos.x) / (dist || 1);
      const dz = (t.z - bot.pos.z) / (dist || 1);
      if (dist > desired + 7) { tx = bot.pos.x + dx * 10; tz = bot.pos.z + dz * 10; }
      else if (dist < desired - 5) { tx = bot.pos.x - dx * 10; tz = bot.pos.z - dz * 10; }
      else {
        tx = bot.pos.x - dz * bot.strafe * 10;
        tz = bot.pos.z + dx * bot.strafe * 10;
      }
      speed = 3.0;
      bot.yaw = angleLerp(bot.yaw, Math.atan2(-(t.x - bot.pos.x), -(t.z - bot.pos.z)), 1 - Math.exp(-7 * dt));
    } else {
      if (Math.hypot(bot.wander.x - bot.pos.x, bot.wander.z - bot.pos.z) < 3) {
        const r = this.game.zone.radius * 0.55;
        bot.wander.set(this.game.zone.x + rand(-r, r), 0, this.game.zone.z + rand(-r, r));
      }
      tx = bot.wander.x; tz = bot.wander.z;
      speed = outside ? 5.1 : 2.8;
      if (outside) speed = 5.2;
    }
    const dx = tx - bot.pos.x, dz = tz - bot.pos.z;
    const d = Math.hypot(dx, dz);
    if (d > 1.0) {
      const vx = dx / d * speed, vz = dz / d * speed;
      bot.pos.x += vx * dt;
      bot.pos.z += vz * dt;
      bot.pos.x = clamp(bot.pos.x, -492, 492);
      bot.pos.z = clamp(bot.pos.z, -492, 492);
      if (!bot.target) bot.yaw = angleLerp(bot.yaw, Math.atan2(-vx, -vz), 1 - Math.exp(-5 * dt));
      this.world.resolveCollision(bot.pos, 0.48);
    }
    if (bot.stuck > 1.1) {
      bot.stuck = 0;
      bot.wander.set(bot.pos.x + rand(-25, 25), 0, bot.pos.z + rand(-25, 25));
      bot.pos.x += rand(-0.5, 0.5);
      bot.pos.z += rand(-0.5, 0.5);
    }
  }

  _shoot(bot, targetPos, dist) {
    const from = new THREE.Vector3(bot.pos.x, bot.pos.y + 1.28, bot.pos.z);
    const isPlayer = bot.targetType === 'player';
    const head = Math.random() < 0.09;
    let chance = clamp(0.54 - dist * 0.0031, 0.1, 0.48) * bot.skill;
    if (isPlayer) {
      if (this.player.p.sprinting) chance *= 0.78;
      if (this.player.p.crouching) chance *= 1.06;
    }
    const hit = Math.random() < chance;
    const aim = new THREE.Vector3(targetPos.x, targetPos.y + (isPlayer ? 1.25 : 1.1), targetPos.z);
    if (!hit) {
      aim.x += rand(-3.2, 3.2);
      aim.y += rand(-1.2, 1.6);
      aim.z += rand(-3.2, 3.2);
    }
    this.effects.tracers.spawn(from, aim, bot.weaponId === 'awm' ? 0xffd27a : 0xff8a4a);
    this.effects.spawn(from, 0xffb35a, 4, 2.4, 7, 0.18);
    if (Math.hypot(bot.pos.x - this.player.p.pos.x, bot.pos.z - this.player.p.pos.z) < 48) {
      this.audio.shot(bot.def.audio);
    }
    if (!hit) return;

    if (isPlayer) {
      const base = bot.weaponId === 'awm' ? 48 : bot.weaponId === 'ump' ? 8 : 10;
      const dmg = base * rand(0.85, 1.15) * (head ? 2 : 1);
      this.player.takeDamage(dmg, bot.name, bot.def.name, head);
    } else if (bot.target && bot.target.alive) {
      const base = bot.weaponId === 'awm' ? 55 : bot.weaponId === 'ump' ? 10 : 13;
      bot.target.health -= base * rand(0.8, 1.2) * (head ? 2 : 1);
      if (bot.target.health <= 0) this.killBot(bot.target, bot, bot.def.name, head);
    }
  }

  clear() {
    this.bots = [];
    this.hitMeshes = [];
  }
}

import * as THREE from '../vendor/three.module.js';
import { World, POIS, HALF, WATER_LEVEL } from './world.js';
import { WEAPONS, makeLootWeapon, makeAmmoBox, makeMedkit } from './weapons.js';
import { AudioEngine } from './audio.js';
import { UI } from './ui.js';
import { Sky, ParticleSystem, TracerSystem } from './effects.js';
import { Player } from './player.js';
import { BotManager } from './bots.js';

const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
const rand = (a, b) => a + Math.random() * (b - a);
const nextFrame = () => new Promise((r) => requestAnimationFrame(() => r()));
const fmtTime = (s) => {
  s = Math.max(0, Math.floor(s));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
};

export class Game {
  constructor() {
    this.canvas = document.getElementById('game-canvas');
    this.ui = new UI();
    this.audio = new AudioEngine(this.ui.settings.volume / 100);
    this.state = 'loading';
    this.time = 0;
    this.matchTime = 0;
    this.lobbyAngle = 0.7;
    this.preferred = WEAPONS[this.ui.profile.preferred] ? this.ui.profile.preferred : 'ak47';
    this.keys = {};
    this.touchMove = { x: 0, y: 0 };
    this.touchLook = { x: 0, y: 0 };
    this.crouchToggle = false;
    this.jumpQueued = false;
    this.loot = [];
    this.nearLoot = null;
    this.bots = [];
    this.zone = null;
    this.matchGroup = null;
    this.matchEnded = false;
    this.pendingResult = null;
    this.fps = 60;
    this.frameCount = 0;
    this.fpsTimer = 0;
    this.minimapTimer = 0;
    this.crosshairTimer = 0;
    this.crosshairEnemy = false;
    this.lastMouse = { x: 0, y: 0 };
    this.isTouch = this.ui.isTouch;
    this._bindUI();
    this._bindInput();
    this.animate = this.animate.bind(this);
    this.init().catch((err) => {
      console.error(err);
      this.ui.setLoading(100, 'FAILED TO START — CHECK CONSOLE');
    });
  }

  _bindUI() {
    this.ui.on('onDeploy', (id) => this.deploy(id));
    this.ui.on('onResume', () => this.resume());
    this.ui.on('onQuit', () => this.quitToLobby());
    this.ui.on('onPlayAgain', () => this.playAgain());
    this.ui.on('onBackLobby', () => this.quitToLobby());
    this.ui.on('onWeaponSelect', (id) => { this.preferred = id; });
    this.ui.on('onSettingsChange', (settings, key) => this.applySettings(key));
    this.ui.on('onUiSound', () => this.audio.ui());
  }

  async init() {
    this.ui.setLoading(4, 'BOOTING WEBGL RENDERER');
    await nextFrame();
    this._setupRenderer();
    this._setupScene();
    this.ui.setLoading(14, 'GENERATING 1 KM² ISLAND');
    await nextFrame();
    await nextFrame();
    this.world = new World(this.scene, this.ui.settings.quality);
    this.ui.setLoading(62, 'GROWING FORESTS & RAISING LANDMARKS');
    await nextFrame();
    this.sky = new Sky(this.scene, this.ui.settings.quality);
    const particles = new ParticleSystem(this.scene, this.ui.settings.quality === 'high' ? 650 : 350);
    const tracers = new TracerSystem(this.scene, 34);
    this.effects = { particles, tracers, spawn: (...args) => particles.spawn(...args) };
    this.ui.setLoading(80, 'DEPLOYING SURVIVORS');
    await nextFrame();
    this.player = new Player(this);
    this.botManager = new BotManager(this);
    this.player.setActive(false);
    this.ui.setWorld(this.world);
    this.applySettings('volume');
    this.ui.setLoading(94, 'CALIBRATING SENSITIVITY');
    await nextFrame();
    this._lobbyCamera(true);
    this.state = 'lobby';
    this.ui.setLoading(100, 'READY TO DEPLOY');
    await new Promise((r) => setTimeout(r, 420));
    this.ui.hideLoading();
    this.ui.showLobby();
    this.ui.setHudVisible(false);
    if (this.isTouch) {
      document.getElementById('mobile-controls').classList.remove('hidden');
      if (window.innerHeight > window.innerWidth) document.getElementById('rotate-hint').classList.remove('hidden');
    }
    this.clock = new THREE.Clock();
    requestAnimationFrame(this.animate);
  }

  _setupRenderer() {
    const quality = this.ui.settings.quality;
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: quality === 'high',
      powerPreference: 'high-performance',
      alpha: false
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, quality === 'high' ? 1.6 : 1));
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.02;
    this.renderer.shadowMap.enabled = quality === 'high';
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }

  _setupScene() {
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.Fog(0xb9c7c9, 200, 820);
    this.camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, 0.06, 1500);
    this.camera.rotation.order = 'YXZ';
    this.scene.add(this.camera);

    this.hemi = new THREE.HemisphereLight(0xcfe8ff, 0x6f684d, 1.35);
    this.scene.add(this.hemi);
    this.sunLight = new THREE.DirectionalLight(0xffe0b8, 2.35);
    this.sunLight.position.set(140, 210, 80);
    this.sunLight.castShadow = this.ui.settings.quality === 'high';
    this.sunLight.shadow.mapSize.set(2048, 2048);
    this.sunLight.shadow.camera.near = 1;
    this.sunLight.shadow.camera.far = 500;
    this.sunLight.shadow.camera.left = -95;
    this.sunLight.shadow.camera.right = 95;
    this.sunLight.shadow.camera.top = 95;
    this.sunLight.shadow.camera.bottom = -95;
    this.sunLight.shadow.bias = -0.0004;
    this.sunLight.target.position.set(0, 0, 0);
    this.scene.add(this.sunLight, this.sunLight.target);
    this.ambient = new THREE.AmbientLight(0xffffff, 0.18);
    this.scene.add(this.ambient);
  }

  _lobbyCamera(initial = false) {
    if (!this.camera) return;
    this.lobbyAngle = initial ? 0.7 : this.lobbyAngle;
    this.camera.fov = 58;
    this.camera.updateProjectionMatrix();
    this.camera.position.set(Math.cos(this.lobbyAngle) * 300, 116, Math.sin(this.lobbyAngle) * 300);
    this.camera.lookAt(10, 22, 5);
    if (this.sunLight) {
      this.sunLight.position.set(140, 210, 80);
      this.sunLight.target.position.set(0, 0, 0);
      this.sunLight.target.updateMatrixWorld();
    }
  }

  animate() {
    requestAnimationFrame(this.animate);
    if (!this.renderer || !this.scene || !this.camera) return;
    const dt = Math.min(0.05, this.clock.getDelta());
    this.time += dt;
    this.world.update(dt, this.time);
    if (this.sky) this.sky.update(dt, this.time);
    if (this.effects) {
      this.effects.particles.update(dt);
      this.effects.tracers.update(dt);
    }
    if (this.state === 'lobby') {
      this.lobbyAngle += dt * 0.035;
      this.camera.position.set(Math.cos(this.lobbyAngle) * 300, 116 + Math.sin(this.lobbyAngle * 0.7) * 8, Math.sin(this.lobbyAngle) * 300);
      this.camera.lookAt(10, 22, 5);
      this.camera.fov = 58;
      this.camera.updateProjectionMatrix();
    } else if (this.state === 'playing') {
      this._updateMatch(dt);
    }
    this.renderer.render(this.scene, this.camera);

    this.frameCount++;
    this.fpsTimer += dt;
    if (this.fpsTimer >= 0.5) {
      this.fps = this.frameCount / this.fpsTimer;
      this.frameCount = 0;
      this.fpsTimer = 0;
      this.ui.setFps(this.fps);
    }
  }

input.oldString:
  if (this.fpsTimer >= 0.5) {
    this.fps = this.frameCount / this.fpsTimer;
    this.frameCount = 0;
    this.fpsTimer = 0;
    this.ui.setFps(this.fps);
  }
}

input.newString:
  if (this.fpsTimer >= 0.5) {
    this.fps = this.frameCount / this.fpsTimer;
    this.frameCount = 0;
    this.fpsTimer = 0;
    this.ui.setFps(this.fps);
  }
}

deploy(preferredId) {
  if (this.state !== 'lobby') return;
  this.audio.init();
  this.audio.setVolume(this.ui.settings.volume / 100);
  this.audio.startAmbience();
  this.preferred = WEAPONS[preferredId] ? preferredId : this.preferred;
  this.ui.hideLobby();
  this.ui.hideResults();
  this.ui.hidePause();
  this.ui.setHudVisible(true);
  this.startMatch(this.preferred);
  this.requestLock();
}

startMatch(preferredId) {
  this.cleanupMatch();
  this.matchEnded = false;
  this.matchTime = 0;
  this.crouchToggle = false;
  this.jumpQueued = false;
  this.nearLoot = null;
  this.crosshairEnemy = false;
  this.matchGroup = new THREE.Group();
  this.scene.add(this.matchGroup);
  this.zone = this._makeZone();
  this._createZoneMesh();

  this.player.resetMatch(preferredId);
  this.player.setActive(true);
  const poi = POIS[Math.floor(Math.random() * POIS.length)];
  const spawn = this.world.randomOpenPosition(poi.x, poi.z, Math.min(75, poi.radius));
  this.player.spawnDrop(spawn.x, spawn.z, rand(-Math.PI, Math.PI), poi.name);
  this.botManager.spawn(23);
  this._spawnLoot();
  this.matchGroup.updateMatrixWorld(true);

  this.ui.lastHud = {};
  this.ui.pickupKey = '';
  this.ui.setPickup(null);
  this.ui.setScope(false);
  document.getElementById('killfeed').innerHTML = '';
  this.ui.showBanner('DROP ZONE', poi.name, 2100);
  this.ui.setHudVisible(true);
  this.ui.hideResults();
  this.ui.hidePause();
  this.state = 'playing';
  this.audio.startAmbience();
  this.camera.fov = 78;
  this.camera.updateProjectionMatrix();
}

cleanupMatch() {
  if (this.pendingResult) { clearTimeout(this.pendingResult); this.pendingResult = null; }
  if (this.matchGroup) {
    this.scene.remove(this.matchGroup);
    this.matchGroup.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
    });
    this.matchGroup = null;
  }
  if (this.botManager) this.botManager.clear();
  if (this.player) this.player.setActive(false);
  this.loot = [];
  this.zone = null;
  this.nearLoot = null;
  if (this.effects) { this.effects.particles.clear(); this.effects.tracers.clear(); }
  this.ui.setScope(false);
  this.ui.setPickup(null);
}

_makeZone() {
  const x = rand(-80, 80), z = rand(-80, 80);
  const zone = {
    x, z, radius: 620,
    phase: 1, state: 'wait', timer: 22,
    shrinkDuration: 22, damage: 1.5,
    startX: x, startZ: z, startRadius: 620,
    targetX: x, targetZ: z, targetRadius: 440,
    nextX: x, nextZ: z, nextRadius: 440
  };
  this._computeNextZone(zone);
  return zone;
}

_computeNextZone(z) {
  const nextRadius = Math.max(24, z.radius * 0.72);
  const maxOffset = Math.max(0, z.radius - nextRadius) * 0.72;
  const a = Math.random() * Math.PI * 2;
  const d = Math.random() * maxOffset;
  z.nextX = clamp(z.x + Math.cos(a) * d, -HALF + 80, HALF - 80);
  z.nextZ = clamp(z.z + Math.sin(a) * d, -HALF + 80, HALF - 80);
  z.nextRadius = nextRadius;
}

_createZoneMesh() {
  const geo = new THREE.CylinderGeometry(1, 1, 150, 64, 1, true);
  const mat = new THREE.MeshBasicMaterial({
    color: 0x8a3cff, transparent: true, opacity: 0.15,
    side: THREE.DoubleSide, depthWrite: false
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(this.zone.x, 70, this.zone.z);
  mesh.scale.set(this.zone.radius, 1, this.zone.radius);
  mesh.renderOrder = 3;
  this.matchGroup.add(mesh);
  this.zoneMesh = mesh;
}

_spawnLoot() {
  const spots = [...this.world.lootSpawns];
  for (let i = spots.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [spots[i], spots[j]] = [spots[j], spots[i]];
  }
  const weaponIds = ['ak47', 'ump', 'ak47', 'awm', 'ump', 'ak47', 'awm', 'ump'];
  let wi = 0;
  for (let i = 0; i < spots.length; i++) {
    const sp = spots[i];
    if (i < 30) {
      const id = weaponIds[wi % weaponIds.length];
      wi++;
      this.spawnLootAt(sp.x, sp.z, 'weapon', id, 0);
    } else if (i < 54) {
      this.spawnLootAt(sp.x, sp.z, 'ammo', null, 0);
    } else if (i < 74) {
      this.spawnLootAt(sp.x, sp.z, 'medkit', null, 0);
    }
  }
}

spawnLootAt(x, z, type, weaponId = null, delay = 0) {
  if (!this.matchGroup) return null;
  let mesh;
  if (type === 'weapon' && weaponId) mesh = makeLootWeapon(weaponId);
  else if (type === 'ammo') mesh = makeAmmoBox();
  else mesh = makeMedkit();
  const y = this.world.groundHeight(x, z, Infinity) + 0.22;
  mesh.position.set(x, y, z);
  mesh.rotation.y = Math.random() * Math.PI * 2;
  mesh.visible = delay <= 0;
  this.matchGroup.add(mesh);
  const item = {
    type, weaponId, x, z, baseY: y, mesh,
    ring: mesh.userData.ring || null,
    taken: false, delay, phase: Math.random() * 6
  };
  this.loot.push(item);
  return item;
}

_updateLoot(dt) {
  let nearest = null, nearestD = 3.8;
  const px = this.player.p.pos.x, pz = this.player.p.pos.z;
  for (const item of this.loot) {
    if (item.taken) continue;
    if (item.delay > 0) {
      item.delay -= dt;
      if (item.delay <= 0) item.mesh.visible = true;
      continue;
    }
    item.mesh.position.y = item.baseY + Math.sin(this.time * 2 + item.phase) * 0.055;
    if (item.ring) item.ring.rotation.z += dt * 1.15;
    const d = Math.hypot(item.x - px, item.z - pz);
    if (d < nearestD) { nearestD = d; nearest = item; }
  }
  this.nearLoot = nearest;
  if (!this.player.p.alive || this.player.p.dropping) {
    this.ui.setPickup(null);
    return;
  }
  if (!nearest) { this.ui.setPickup(null); return; }
  this.ui.setPickup(this._pickupPrompt(nearest));
}

_pickupPrompt(item) {
  if (item.type === 'weapon') {
    const def = WEAPONS[item.weaponId];
    const owned = this.player.p.slots.some((s) => s && s.id === item.weaponId);
    const empty = this.player.p.slots.some((s) => !s);
    if (owned) return { action: 'AMMO', name: def.name, sub: '+ RESERVE AMMO' };
    return { action: empty ? 'PICK UP' : 'SWAP', name: def.name, sub: def.category };
  }
  if (item.type === 'ammo') return { action: 'PICK UP', name: 'AMMO BOX', sub: '+ RESERVE' };
  return { action: 'PICK UP', name: 'MEDKIT', sub: '+1 MEDKIT' };
}

pickupNearest() {
  if (this.state !== 'playing' || !this.nearLoot) return;
  this._pickupItem(this.nearLoot);
}

_pickupItem(item) {
  if (!item || item.taken || item.delay > 0) return;
  if (item.type === 'weapon') {
    const def = WEAPONS[item.weaponId];
    const res = this.player.giveWeapon(item.weaponId);
    if (res.oldId) {
      this.spawnLootAt(this.player.p.pos.x + rand(-1.4, 1.4), this.player.p.pos.z + rand(-1.4, 1.4), 'weapon', res.oldId, 1.5);
    }
    this.ui.showBanner('LOOT', `${def.name} ${res.type === 'ammo' ? 'AMMO' : 'ACQUIRED'}`, 900);
    this.audio.pickup();
  } else if (item.type === 'ammo') {
    this.player.giveAmmo(30);
    this.ui.showBanner('LOOT', '+30 RESERVE AMMO', 850);
    this.audio.pickup();
  } else if (item.type === 'medkit') {
    if (this.player.p.medkits >= 5) {
      this.ui.showBanner('MEDKIT', 'MEDKIT POUCH FULL', 900);
      return;
    }
    this.player.giveMedkit();
    this.ui.showBanner('LOOT', '+1 MEDKIT', 850);
    this.audio.pickup();
  }
  item.taken = true;
  item.mesh.visible = false;
  if (this.nearLoot === item) this.nearLoot = null;
  this.ui.setPickup(null);
}

