19: export function rankFor(rp) {
20:   const points = Math.max(0, Math.min(3999, Math.round(rp)));
21:   let current = RANKS[0];
22:   for (const r of RANKS) if (points >= r.min) current = r;
23:   const next = RANKS.find(r => r.min > points) || null;
24:   const span = current.max - current.min;
25:   const progress = next ? Math.min(1, (points - current.min) / span) : 1;
26:   return { current, next, progress, points };
27: }
