import { Game } from './game.js';

function boot() {
  try {
    window.firezone = new Game();
  } catch (err) {
    console.error('[FIREZONE] failed to boot', err);
    const text = document.getElementById('loader-text');
    const pct = document.getElementById('loader-pct');
    if (text) text.textContent = 'FAILED TO START — CHECK CONSOLE';
    if (pct) pct.textContent = 'ERR';
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot, { once: true });
} else {
  boot();
}

content.text:
Add CSS for hud-pause and settings overlay. Need ensure `.lobby-screen.show-settings .lobby-panel.settings-panel` works at >960 already panel visible; toggle currently just adds class but no effect on desktop except animation. Fine. For mobile, add media block near responsive. Also maybe desktop show-settings no need.

Add CSS:
```
.hud-pause { pointer-events:auto; width:28px... }
```
After fps-meter.

Settings mobile:
```
@media (max-width:960px){
 .lobby-screen.show-settings .lobby-panel.settings-panel { display:block; position:absolute; left:50%; top:50%; transform:translate(-50%,-50%); width:min(420px,calc(100vw - 32px)); max-height:calc(100% - 24px); overflow:auto; z-index:8; }
 .lobby-screen.show-settings .lobby-hero { opacity:.18; pointer-events:none; filter:blur(2px); }
}
```
But `.lobby-content` has padding and position relative. Top 50% of content area, okay. Panel's `.lobby-panel` align-self center; absolute overrides. `max-height:100%` from base maybe okay, but use 100%.

Need also settings panel hidden on <=960 default via `.lobby-screen .lobby-panel{display:none}`; show-settings specificity wins. Good.

Add touch pickup prompt hide keyboard and touch hint maybe. Not necessary.

Also `.touch .controls-hint {display:none}` already.

Let's add.

