@media (max-width: 960px) {
  .lobby-content { grid-template-columns: minmax(390px, 1fr) minmax(210px, 240px); }
  .rank-panel { display: none; }
  .settings-panel { display: none; }
  .lobby-hero { grid-column: 1 / -1; }
  .lobby-screen .lobby-panel { display: none; }
  .lobby-content { grid-template-columns: 1fr; }
  .game-title { font-size: clamp(54px, 11vw, 92px); }
  .lobby-topbar { padding-left: calc(18px + var(--safe-l)); padding-right: calc(18px + var(--safe-r)); }
  .online-pill { display: none; }

  /* The settings panel becomes a centered sheet on tablets and phones. */
  .lobby-screen.show-settings .lobby-panel.settings-panel {
    display: block; position: absolute; z-index: 8;
    left: 50%; top: 50%; transform: translate(-50%, -50%);
    width: min(430px, calc(100vw - 34px)); max-height: calc(100% - 20px);
    overflow: auto; padding: 20px 20px 18px;
    box-shadow: 0 30px 90px rgba(0,0,0,.78);
  }
  .lobby-screen.show-settings .lobby-hero {
    opacity: .16; filter: blur(2px); pointer-events: none;
  }
}

